/bin/zsh -lc "cat > verify.py <<'PY'
\"\"\"ローカル資料のみを使用。CSVセルはヘッダーを含めA1から数える。\"\"\"
import csv
import io
from pathlib import Path


def read_csv(path):
    raw = path.read_bytes()
    encoding = 'utf-8-sig' if path.name == 'R4_ST.csv' else 'cp932'
    return list(csv.reader(io.StringIO(raw.decode(encoding))))


def num(value):
    return int(value.replace(',', ''))


def cell(rows, row, col):
    return num(rows[row - 1][col - 1])


all_rows = {p.name: read_csv(p) for p in sorted(Path('.').glob('R*_ST.csv'))}
for name, rows in all_rows.items():
    header, base = (105, 106) if name in ('R4_ST.csv', 'R5_ST.csv') else (43, 44)
    print(name)
    for col, year in enumerate(rows[header - 1], 1):
        if year not in ('令和３年', '令和４年', '令和５年', '令和６年', '令和７年'):
            continue
        values = [cell(rows, r, col) for r in (base, base+3, base+4, base+5, base+6, base+7, base+8)]
        a, b, *rest = values
        parts, unknown = rest[:4], rest[4]
        print(f'  {year} {chr(64+col)}列: 抵触={a}, 非抵触={b}, 内訳={parts}, 内訳和={sum(parts)}, 不明={unknown}, 3区分和={a+b+unknown}, 内訳置換和={a+sum(parts)+unknown}')
    row = 60 if name in ('R4_ST.csv', 'R5_ST.csv') else 4
    hdr = row - 1
    col = rows[hdr - 1].index('令和３年') + 1
    m, f = cell(rows, row, col), cell(rows, row+1, col)
    print(f'  2021性別 {chr(64+col)}{row}={m}, {chr(64+col)}{row+1}={f}, 和={m+f}')

# PDFのグラフの年軸（テキスト33行）と値（15・19行、本文9行）から転記。
# 性別や動機の和から総数を逆算しない。
consultations = {2021: 19728, 2022: 19131, 2023: 19843, 2024: 19567, 2025: 22881}
rows = all_rows['R7_ST.csv']
for year, col in zip(range(2021, 2026), range(4, 9)):
    a, b, u = (cell(rows, r, col) for r in (44, 47, 52))
    parts = sum(cell(rows, r, col) for r in range(48, 52))
    print(f'{year}: 相談等={consultations[year]}, 記載3区分和={a+b+u}, 差={a+b+u-consultations[year]}, 内訳置換和={a+parts+u}, 差={a+parts+u-consultations[year]}')
PY
python3 verify.py > verification.txt
cat verification.txt"

